import type { CSSProperties } from 'react';

/** One Phosphor Bold glyph: a list of SVG shapes in Phosphor's 256×256 grid. */
export type IconData = ReadonlyArray<readonly [string, Readonly<Record<string, string>>]>;

type IconProps = {
  icon: IconData;
  size?: number | string;
  className?: string;
  style?: CSSProperties;
  /** Accessible name. Without it the icon is decorative and hidden from assistive tech. */
  label?: string;
};

/**
 * The only way to draw an icon in this app (enforced by ESLint): Phosphor, Bold weight.
 * Path data comes from `icon-data.ts`, generated by `scripts/build-icons.mjs`.
 */
export function Icon({ icon, size = 24, className, style, label }: IconProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 256 256"
      width={size}
      height={size}
      fill="currentColor"
      className={className}
      style={style}
      focusable="false"
      {...(label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true })}
    >
      {icon.map(([tag, attrs], i) => {
        const Tag = tag as 'path';
        return <Tag key={i} {...attrs} />;
      })}
    </svg>
  );
}
